contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 < 2**128 && amount2 < 2**128);
        require(address(this).balance >= amount1 + amount2);
        // initial full cycle
        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        // after the cycle, a fresh deposit must be accounted exactly
        uint before = address(c).balance;
        uint myBefore = address(this).balance;
        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        uint cAfter = address(c).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint myAfter = address(this).balance;
        assert(cAfter == before + amount2 && myAfter >= myBefore);
    }
    receive() external payable {}
}

