// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 < 2**128 && amount2 < 2**128);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.deposit{value: amount1}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint before = address(c).balance;
        uint myBefore = address(this).balance;
        try c.deposit{value: amount2}() {} catch { return; }
        uint cAfter = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint myAfter = address(this).balance;
        assertTrue(cAfter == before + amount2 && myAfter >= myBefore);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
